from rdkit import Chem
import numpy as np
m=Chem.MolFromMolFile('initial.mol',removeHs=False)
a=np.loadtxt('answer.xyz',skiprows=2,usecols=[1,2,3])
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
 print(f'{i+1:2} {j+1:2} {np.linalg.norm(a[i]-a[j]):.3f}')
print('Unintended close contacts:')
for i in range(len(a)):
 for j in range(i):
  if not m.GetBondBetweenAtoms(i,j) and np.linalg.norm(a[i]-a[j])<1.7: print(i+1,j+1,np.linalg.norm(a[i]-a[j]))
